import math
def ring_cells(k):
    cells=[]
    for r in range(20):
        for c in range(20):
            if max(abs(r-5),abs(c-7))==k: cells.append((r,c))
    # sort clockwise starting from top-left corner of ring
    cr,cc=5,7
    def ang(rc):
        r,c=rc
        return (math.atan2(-(r-cr), c-cc))  # standard math angle, y up
    cells.sort(key=lambda rc:(-ang(rc)))
    return cells
for k in range(2,15,2):
    cells=ring_cells(k)
    s=''.join('#' if out[r][c]==4 else '.' for r,c in cells)
    print(k, len(cells), s)

import math
def ring_cells_cw(k):
    cells=[]
    for r in range(20):
        for c in range(20):
            if max(abs(r-5),abs(c-7))==k: cells.append((r,c))
    cr,cc=5,7
    cells.sort(key=lambda rc:-math.atan2(-(rc[0]-cr), rc[1]-cc))
    return cells
for k in range(2,15,2):
    cells=ring_cells_cw(k)
    gaps=[i for i,(r,c) in enumerate(cells) if out[r][c]==0]
    # also absolute angle of each gap
    angs=[]
    for i in gaps:
        r,c=cells[i]
        a=math.degrees(math.atan2(5-r, c-7))%360
        angs.append(round(a))
    print(k, gaps, angs)
